# Rate limiting zone: 20 requests per second per IP, 10MB zone (approx. 160k IPs)
limit_req_zone $binary_remote_addr zone=api_limit:10m rate=20r/s;

# Upstream definition for the backend API
upstream api_backend {
    server 127.0.0.1:8080;
    keepalive 32;
}

# HTTP server: redirect all traffic to HTTPS
server {
    listen 80;
    listen [::]:80;
    server_name _;

    # Redirect all HTTP requests to HTTPS
    return 301 https://$host$request_uri;
}

# HTTPS server: reverse proxy with security and performance features
server {
    listen 443 ssl http2;
    listen [::]:443 ssl http2;
    server_name _;

    # --- TLS Configuration ---
    ssl_certificate /etc/nginx/ssl/server.crt;
    ssl_certificate_key /etc/nginx/ssl/server.key;

    # Modern TLS protocols only
    ssl_protocols TLSv1.2 TLSv1.3;

    # Modern cipher suite (prioritizing forward secrecy and AEAD ciphers)
    ssl_ciphers ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256:ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384:ECDHE-ECDSA-CHACHA20-POLY1305:ECDHE-RSA-CHACHA20-POLY1305:DHE-RSA-AES128-GCM-SHA256:DHE-RSA-AES256-GCM-SHA384;

    # Prefer server cipher order
    ssl_prefer_server_ciphers on;

    # Session cache for performance
    ssl_session_cache shared:SSL:10m;
    ssl_session_timeout 1d;
    ssl_session_tickets off;

    # OCSP stapling
    ssl_stapling on;
    ssl_stapling_verify on;
    resolver 8.8.8.8 8.8.4.4 valid=300s;
    resolver_timeout 5s;

    # --- Gzip Compression ---
    gzip on;
    gzip_vary on;
    gzip_proxied any;
    gzip_comp_level 6;
    gzip_min_length 256;
    gzip_types
        application/json
        application/javascript
        text/css
        text/xml
        application/xml
        application/xml+rss
        text/plain;

    # --- Health Check Endpoint (exempt from access logging) ---
    location /health {
        access_log off;
        proxy_pass http://api_backend;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }

    # --- Main API Proxy ---
    location / {
        # Rate limiting: 20 req/s per IP, burst of 40, return 429 on excess
        limit_req zone=api_limit burst=40 nodelay;

        # Proxy timeouts: 30 seconds for connect, send, and read
        proxy_connect_timeout 30s;
        proxy_send_timeout 30s;
        proxy_read_timeout 30s;

        # WebSocket upgrade support
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";

        # Standard proxy headers
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;

        # Pass request to upstream
        proxy_pass http://api_backend;

        # Disable buffering for real-time responses (e.g., websockets, SSE)
        proxy_buffering off;
    }
}
