//! A module providing merge sort implementations in Rust.

/// Sorts a slice using the merge sort algorithm and returns a new sorted `Vec`.
///
/// # Complexity
///
/// - **Time:** O(n log n) in all cases (best, average, worst).
/// - **Space:** O(n) auxiliary space for the temporary arrays used during merging.
///
/// # Arguments
///
/// * `v` - A slice of elements that implement `Ord` and `Clone`.
///
/// # Returns
///
/// A new `Vec<T>` containing the sorted elements.
///
/// # Examples
///
/// ```
/// use my_module::merge_sort;
///
/// let v = vec![3, 1, 4, 1, 5, 9, 2, 6];
/// let sorted = merge_sort(&v);
/// assert_eq!(sorted, vec![1, 1, 2, 3, 4, 5, 6, 9]);
/// ```
pub fn merge_sort<T: Ord + Clone>(v: &[T]) -> Vec<T> {
    if v.len() <= 1 {
        return v.to_vec();
    }

    let mid = v.len() / 2;
    let left = merge_sort(&v[..mid]);
    let right = merge_sort(&v[mid..]);

    merge(&left, &right)
}

/// Merges two sorted slices into a single sorted `Vec`.
///
/// # Complexity
///
/// - **Time:** O(n + m) where n and m are the lengths of the two input slices.
/// - **Space:** O(n + m) for the output vector.
fn merge<T: Ord + Clone>(left: &[T], right: &[T]) -> Vec<T> {
    let mut result = Vec::with_capacity(left.len() + right.len());
    let mut i = 0;
    let mut j = 0;

    while i < left.len() && j < right.len() {
        if left[i] <= right[j] {
            result.push(left[i].clone());
            i += 1;
        } else {
            result.push(right[j].clone());
            j += 1;
        }
    }

    // Append remaining elements
    while i < left.len() {
        result.push(left[i].clone());
        i += 1;
    }
    while j < right.len() {
        result.push(right[j].clone());
        j += 1;
    }

    result
}

/// Sorts a slice in-place using the merge sort algorithm.
///
/// This variant uses O(n) auxiliary space for temporary buffers but modifies
/// the input slice in place.
///
/// # Complexity
///
/// - **Time:** O(n log n) in all cases (best, average, worst).
/// - **Space:** O(n) auxiliary space for temporary buffers used during merging.
///
/// # Arguments
///
/// * `v` - A mutable slice of elements that implement `Ord`.
///
/// # Examples
///
/// ```
/// use my_module::merge_sort_in_place;
///
/// let mut v = vec![3, 1, 4, 1, 5, 9, 2, 6];
/// merge_sort_in_place(&mut v);
/// assert_eq!(v, vec![1, 1, 2, 3, 4, 5, 6, 9]);
/// ```
pub fn merge_sort_in_place<T: Ord>(v: &mut [T]) {
    if v.len() <= 1 {
        return;
    }

    let mid = v.len() / 2;
    merge_sort_in_place(&mut v[..mid]);
    merge_sort_in_place(&mut v[mid..]);

    // Use a temporary buffer for merging
    let mut temp = vec![v[0].clone(); v.len()];
    merge_in_place(v, &mut temp, 0, mid, v.len());
}

/// Helper function to merge two sorted halves of a slice in-place using a temporary buffer.
///
/// # Complexity
///
/// - **Time:** O(n) where n is the length of the slice being merged.
/// - **Space:** O(n) for the temporary buffer.
fn merge_in_place<T: Ord + Clone>(v: &mut [T], temp: &mut [T], left: usize, mid: usize, right: usize) {
    // Copy the relevant portion into temp
    for i in left..right {
        temp[i] = v[i].clone();
    }

    let mut i = left;
    let mut j = mid;
    let mut k = left;

    while i < mid && j < right {
        if temp[i] <= temp[j] {
            v[k] = temp[i].clone();
            i += 1;
        } else {
            v[k] = temp[j].clone();
            j += 1;
        }
        k += 1;
    }

    // Copy remaining elements from the left half
    while i < mid {
        v[k] = temp[i].clone();
        i += 1;
        k += 1;
    }

    // No need to copy remaining elements from the right half
    // as they are already in their correct positions in v
}

