// worker is the main loop for a single worker goroutine.
func (p *Pool) worker() {
	defer p.wg.Done()
	for task := range p.tasks {
		p.execute(task)
	}
}

// execute runs a single task, recovering from panics and collecting errors.
func (p *Pool) execute(task func() error) {
	defer func() {
		if r := recover(); r != nil {
			p.mu.Lock()
			p.panics = append(p.panics, r)
			p.mu.Unlock()
			// Send a panic error to the error channel.
			select {
			case p.errCh <- fmt.Errorf("panic in worker: %v", r):
			default:
			}
		}
	}()
	if err := task(); err != nil {
		select {
		case p.errCh <- err:
		default:
		}
	}
}

// Submit enqueues a function to be executed by a worker.
// It returns an error if the pool has been shut down.
func (p *Pool) Submit(fn func() error) error {
	p.mu.Lock()
	defer p.mu.Unlock()
	if p.shutdown {
		return errors.New("pool is shut down")
	}
	p.tasks <- fn
	return nil
}

// Errors returns a channel that receives errors from executed tasks.
// The channel is closed when the pool is fully shut down and all in-flight
// work has completed.
func (p *Pool) Errors() <-chan error {
	return p.errCh
}

// Panics returns a snapshot of all panics recovered from workers.
func (p *Pool) Panics() []any {
	p.mu.Lock()
	defer p.mu.Unlock()
	out := make([]any, len(p.panics))
	copy(out, p.panics)
	return out
}

// Shutdown gracefully shuts down the pool. It waits for all in-flight work
// to complete before closing the error channel. The provided context can be
// used to cancel the wait; if the context is cancelled before all work
// completes, Shutdown returns the context error.
func (p *Pool) Shutdown(ctx context.Context) error {
	p.mu.Lock()
	if p.shutdown {
		p.mu.Unlock()
		return nil
	}
	p.shutdown = true
	p.mu.Unlock()

	// Close the tasks channel to signal workers to drain and exit.
	close(p.tasks)

	// Wait for all workers to finish.
	done := make(chan struct{})
	go func() {
		p.wg.Wait()
		close(done)
	}()

	select {
	case <-done:
		// All workers finished; close the error channel.
		close(p.errCh)
		return nil
	case <-ctx.Done():
		// Context was cancelled before all work completed.
		// We still close the error channel to avoid leaking, but return the ctx error.
		close(p.errCh)
		return ctx.Err()
	}
}
